import{z as o,x as A,o as r,c as B,q as t,j as n,D as e,d as i,s as l,S as s}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"Generative Agents","description":"","frontmatter":{"title":"Generative Agents","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/generative-agents.md","filePath":"llm/generative-agents.md","lastUpdated":1791063341000}'),p={name:"llm/generative-agents.md"};function g(d,a,h,m,c,u){const E=A("Mermaid");return r(),B("div",null,[a[2]||(a[2]=t('<h1 id="generative-agents" tabindex="-1">Generative Agents <a class="header-anchor" href="#generative-agents" aria-label="Permalink to &quot;Generative Agents&quot;">​</a></h1><div class="epigraph"><p>把每个智能体的经历写成自然语言流水账，按近因、重要性和相关性检索，再周期性反思成更高层的判断，并用这些记忆递归做成一天的计划—— believable 的行为来自记忆架构，而不是来自更长的单次提示。</p><footer>—— Park 等，Generative Agents: Interactive Simulacra of Human Behavior，UIST 2023</footer></div><p>Joon Sung Park、Joseph C. O’Brien、Carrie J. Cai、Meredith Ringel Morris、Percy Liang 与 Michael S. Bernstein（Stanford / Google）的 UIST 2023 论文（arXiv:2304.03442，DOI: 10.1145/3586183.3606763）给出 <strong>generative agents</strong>：在类《模拟人生》的沙盒 <strong>Smallville</strong> 里安置 25 个角色，用 GPT-3.5 驱动观察、记忆、反思与规划。智能体起床、上班、聊天、形成关系；从一条「想办情人节派对」的种子意图，涌现出邀请、布置、赴约。评测分受控访谈与端到端两日模拟。本篇写记忆流与检索公式、反思如何写回记忆、计划如何拆成时刻表。应用是社会原型与角色扮演排练，工作流止于沙盒内交互，不涉及操纵真实人类或攻击性社会工程。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>要把「可信的人」放进互动环境，不能每一步把一生经历塞进上下文：窗口不够，噪声还会淹没当下。只根据当前观察生成下一句，角色会忘早上的约定、与每个人的关系归零。需要长期记忆模块：完整记录经验，动态取出与此刻相关的子集，并随时间合成更高层的自我与社会判断，再变成可执行的日程。</p><p><span class="marginnote">记忆流可以类比一本「人生流水账日记」：所有事原样记下，不摘要、不挑拣。要行动时不是重读整本，而是按「最近写的、分量重的、和眼前情形像不像」三个条件翻出相关几页。简历式的「角色卡摘要」省纸，但会弄丢「今天下午三点有约」这种细节——角色立刻就显得假。</span></p><p>Smallville 提供咖啡馆、公园、住宅、物件状态（炉子开着、冰箱空了）。用户可用自然语言改物件状态，智能体应在下一刻感知并反应。架构必须同时服务：<strong>单独一人是否像该角色</strong>，以及<strong>许多人互动是否涌现出传播、关系、协作</strong>。</p><h3 id="记忆流不是向量数据库里的-rag-问答" tabindex="-1">记忆流不是向量数据库里的 RAG 问答 <a class="header-anchor" href="#记忆流不是向量数据库里的-rag-问答" aria-label="Permalink to &quot;记忆流不是向量数据库里的 RAG 问答&quot;">​</a></h3><p>每条记录是带时间戳的自然语言观察：「冰箱空闲」「在公园遇见 Latoya，她在做摄影项目」。检索不是为了回答用户百科，而是为了条件化「现在做什么、对谁说什么」。反思与计划也会作为记录写回，成为未来检索的对象。这与 Voyager 的技能库不同：那边存可执行代码，这边存经历与态度。</p><p><span class="marginnote">实现用当时的 gpt-3.5-turbo；作者预期换 GPT-4 只增强提示表现，不改记忆–反思–规划三件套。引用行为案例时应区分「架构涌现」与「模型随机编造的记忆」——后者是论文点名的失败模式。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>架构三件。<strong>(1) 记忆流</strong>： perceiver 把环境事件追加为观察。<strong>(2) 检索</strong>：对当前查询（例如「你现在最期待什么」）给每条记忆打分，近因、重要性、相关性加权求和，取 top 若干条送进提示。重要性由模型对「这件事对角色有多重要」打 1–10；相关性是嵌入余弦；近因是时间衰减。<strong>(3) 反思</strong>：当重要性累积过阈值，提示模型基于最近记忆生成更高层结论（「Klaus 热爱写作」），写入记忆流。<strong>(4) 规划</strong>：先生成当天高层计划，再递归拆到小时与分钟级动作；遇打断则反应并可能改计划。对话与移动由沙盒引擎执行路径。</p><p><span class="marginnote">重要性打分代入个数：「刷牙」可能被打 1 分，「初次遇见 Klaus」打 7 分，「决定办情人节派对」打 9 分。只有高分记忆积累到阈值才触发反思——相当于给经历装了一个「这件事值得想一想」的门槛，而不是所有观察都等权重地堆进人生结论里。</span></p><p>25 个智能体各有一段种子人设（职业、关系）。端到端例子：Isabella 被初始化为要在 Hobbs Cafe 办情人节派对；之后邀请、请 Maria 帮忙布置、Maria 邀请 Klaus，当日多人到场——传播与赴约不是脚本分支，是记忆与计划交互的结果。</p>',14)),(r(),n(s,null,{default:e(()=>[l(E,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20OBS%5B%22%E7%8E%AF%E5%A2%83%E8%A7%82%E5%AF%9F%22%5D%20--%3E%20MS%5B%22%E8%AE%B0%E5%BF%86%E6%B5%81%E8%BF%BD%E5%8A%A0%22%5D%0A%20%20MS%20--%3E%20RET%5B%22%E8%BF%91%E5%9B%A0%20%C3%97%20%E9%87%8D%E8%A6%81%E6%80%A7%20%C3%97%20%E7%9B%B8%E5%85%B3%22%5D%0A%20%20RET%20--%3E%20REF%5B%22%E5%91%A8%E6%9C%9F%E6%80%A7%E5%8F%8D%E6%80%9D%E5%86%99%E5%9B%9E%22%5D%0A%20%20REF%20--%3E%20MS%0A%20%20RET%20--%3E%20PLN%5B%22%E6%97%A5%E8%AE%A1%E5%88%92%E9%80%92%E5%BD%92%E6%8B%86%E8%A7%A3%22%5D%0A%20%20PLN%20--%3E%20ACT%5B%22%E5%8A%A8%E4%BD%9C%20%2F%20%E5%AF%B9%E8%AF%9D%22%5D%0A%20%20ACT%20--%3E%20ENV%5B%22Smallville%20%E7%8A%B6%E6%80%81%E6%9B%B4%E6%96%B0%22%5D%0A%20%20ENV%20--%3E%20OBS%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p>评测：用自然语言「访谈」智能体，测是否还记得人设、计划、关系、能否反思；消融去掉记忆、反思或规划，访谈分数下降，说明三件套各自必要。端到端看信息是否扩散、关系是否更新、派对是否发生。失败集中在：检索漏掉关键记忆、对记忆添油加醋、口吻过于正式。</p><h3 id="检索分数是架构的旋钮" tabindex="-1">检索分数是架构的旋钮 <a class="header-anchor" href="#检索分数是架构的旋钮" aria-label="Permalink to &quot;检索分数是架构的旋钮&quot;">​</a></h3><p>只有近因，角色变成金鱼；只有重要性，日常走路挤不进窗口；只有相关性，会翻出语义相近但过期的事。三者相加是工程折中，权重需调。反思频率过高会把噪声上升成性格，过低则不会出现「我对 Klaus 有好感」这种能改变邀请行为的中间变量。计划递归深度决定是「上午工作」还是「10:15 去拿咖啡」——过细则调用次数爆炸（25 人 × 每时刻一次 LLM）。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>可信性来自条件前缀的一致性：同一 Isabella 在不同时刻检索到重叠的派对相关记忆，言行才不会自相矛盾。涌现不是额外模块，而是多个检索–生成循环通过共享环境状态耦合：A 对 B 说「有派对」，该观察进入 B 的记忆流，B 的计划被改写。消融证明：没有记忆则访谈与协作都垮；没有反思则难以形成稳定态度；没有计划则行为碎成对瞬时观察的反应，像只有 ReAct、没有日程。</p><p><span class="marginnote">初学者容易以为情人节派对是作者写好的剧情脚本。设计恰恰相反：种子只有「Isabella 想办派对」一条，邀请谁、请谁布置、谁到场，全是各角色检索记忆、改计划、互相对话的产物。要检验是否真涌现，看的就是架构里有没有硬编码分支。</span></p><p>一条记忆是怎么被挑进提示的：</p>',7)),(r(),n(s,null,{default:e(()=>[l(E,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20LR%0A%20%20M%5B%22%E4%B8%80%E6%9D%A1%E5%B8%A6%E6%97%B6%E9%97%B4%E6%88%B3%E7%9A%84%E8%AE%B0%E5%BF%86%22%5D%20--%3E%20R%5B%22%E8%BF%91%E5%9B%A0%EF%BC%9A%E8%B6%8A%E6%96%B0%E5%88%86%E8%B6%8A%E9%AB%98%3Cbr%2F%3E%E6%8C%89%E6%97%B6%E9%97%B4%E8%A1%B0%E5%87%8F%22%5D%0A%20%20M%20--%3E%20I%5B%22%E9%87%8D%E8%A6%81%E6%80%A7%EF%BC%9A%E6%A8%A1%E5%9E%8B%E6%89%93%201%E2%80%9310%22%5D%0A%20%20M%20--%3E%20C%5B%22%E7%9B%B8%E5%85%B3%E6%80%A7%EF%BC%9A%E4%B8%8E%E5%BD%93%E4%B8%8B%E6%83%85%E5%A2%83%E7%9A%84%E5%B5%8C%E5%85%A5%E4%BD%99%E5%BC%A6%22%5D%0A%20%20R%20--%3E%20S%5B%22%E4%B8%89%E9%A1%B9%E5%8A%A0%E6%9D%83%E6%B1%82%E5%92%8C%22%5D%0A%20%20I%20--%3E%20S%0A%20%20C%20--%3E%20S%0A%20%20S%20--%3E%20T%7B%22%E6%8E%92%E5%90%8D%E8%BF%9B%20top%EF%BC%9F%22%7D%0A%20%20T%20--%3E%7C%E6%98%AF%7C%20P%5B%22%E6%8B%BC%E8%BF%9B%E6%8F%90%E7%A4%BA%EF%BC%8C%E6%9D%A1%E4%BB%B6%E5%8C%96%E4%B8%8B%E4%B8%80%E5%8F%A5%22%5D%0A%20%20T%20--%3E%7C%E5%90%A6%7C%20Q%5B%22%E7%95%99%E5%9C%A8%E6%B5%81%E9%87%8C%E7%AD%89%E4%B8%8B%E6%AC%A1%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p>与 WebGPT / ReAct：那些系统为了一个用户问题优化一条轨迹；generative agents 为每个角色维护一生的流，目标函数是 believable，不是 QA 准确率。与 HuggingGPT：没有专家模型完成感知，观察由沙盒符号状态生成。应用上，论文设想面试排练、社交产品原型；用户进入沙盒也是一个智能体，居民一视同仁。</p><p><span class="marginnote">不要把「25 人小镇」写成通用多人在线模拟器的性能结论。LLM 调用次数与记忆条数线性恶化，检索会成为瓶颈。论文环境是作者手搭的地图，不是程序化生成世界。</span></p><h3 id="访谈评测测的是记忆架构-不是道德判断" tabindex="-1">访谈评测测的是记忆架构，不是道德判断 <a class="header-anchor" href="#访谈评测测的是记忆架构-不是道德判断" aria-label="Permalink to &quot;访谈评测测的是记忆架构，不是道德判断&quot;">​</a></h3><p>问「你在期待什么」时，若检索命中布置派对的记忆，回答会具体；若把记忆摘要成「我喜欢整洁」，就不可信。这解释了为何作者反对「把一生摘要进提示」：摘要丢失了检索该保住的具体事件。添油加醋则是模型在检索不足时用语言模型先验补全，看起来更戏剧，却破坏模拟的因果账本——产品若要可调试，应记录每次检索命中的 id。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>成本：每智能体每时间步多次调用，25 人两日游戏时间是研究级账单。记忆造假与过度礼貌是模型先验，单靠架构消不掉。沙盒物件状态是符号化的，没有真实物理。不要用于未经同意地模拟真实个体，或生成操纵性话术去对真实用户使用；论文场景是游戏式小镇与设计原型。规划过期（炉子着火）依赖下一观察进入记忆——若感知漏了，计划会继续做早餐。换更强骨干可能减少正式口吻，但检索漏记仍在。</p><p><span class="marginnote">出处：Park, O’Brien, Cai, Morris, Liang, Bernstein，<em>Generative Agents: Interactive Simulacra of Human Behavior</em>，UIST 2023，arXiv:2304.03442。演示与代码见论文项目链接。对照具身代码技能见 Voyager。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Generative agents 用记忆流 + 近因/重要性/相关性检索 + 反思 + 递归规划驱动可信日常行为。</li><li>Smallville 中 25 个角色展现信息扩散、关系形成与派对协作等涌现。</li><li>消融表明三件套缺一不可；失败多为检索遗漏或对记忆虚构。</li><li>出处：Park et al.，UIST 2023。</li></ul>',9))])}const D=o(p,[["render",g]]);export{_ as __pageData,D as default};
